import{_ as d,c as e,o as r,b2 as a}from"./chunks/framework.CUhoHPxN.js";const m=JSON.parse('{"title":"用户管理","description":"","frontmatter":{},"headers":[],"relativePath":"docs/backend/modules/user-management.md","filePath":"docs/backend/modules/user-management.md"}'),o={name:"docs/backend/modules/user-management.md"};function c(s,t,l,i,n,h){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="用户管理" tabindex="-1">用户管理 <a class="header-anchor vp-link" href="#用户管理" aria-label="Permalink to &quot;用户管理&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor vp-link" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>系统用户 CRUD、状态切换、密码重置、角色授权、Excel 导入导出。</p><div class="vp-table"><table><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>Controller</td><td><code>SysUserController</code></td></tr><tr><td>基础路径</td><td><code>/system/user</code></td></tr><tr><td>前端页面</td><td><code>quick-ui/src/views/system/user/</code></td></tr><tr><td>API</td><td><code>quick-ui/src/api/system/user.js</code></td></tr><tr><td>数据表</td><td><code>sys_user</code>（及用户角色关联表）</td></tr></tbody></table></div><h2 id="主要接口" tabindex="-1">主要接口 <a class="header-anchor vp-link" href="#主要接口" aria-label="Permalink to &quot;主要接口&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>方法</th><th>路径</th><th>说明</th></tr></thead><tbody><tr><td>GET</td><td><code>/list</code></td><td>分页列表（支持部门、状态等筛选）</td></tr><tr><td>GET</td><td><code>/{userId}</code></td><td>用户详情</td></tr><tr><td>POST</td><td><code>/create</code></td><td>新增</td></tr><tr><td>POST</td><td><code>/update</code></td><td>修改</td></tr><tr><td>POST</td><td><code>/remove</code></td><td>删除（逻辑删除）</td></tr><tr><td>POST</td><td><code>/changeStatus</code></td><td>启用/停用</td></tr><tr><td>POST</td><td><code>/resetPwd</code></td><td>重置密码</td></tr><tr><td>GET</td><td><code>/authRole/{userId}</code></td><td>查询已分配角色</td></tr><tr><td>POST</td><td><code>/authRole</code></td><td>保存用户角色</td></tr><tr><td>POST</td><td><code>/importData</code></td><td>Excel 导入（multipart）</td></tr><tr><td>GET</td><td><code>/importTemplate</code></td><td>下载导入模板</td></tr><tr><td>GET</td><td><code>/importError</code></td><td>下载导入失败明细</td></tr><tr><td>POST</td><td><code>/export</code></td><td>导出 Excel</td></tr></tbody></table></div><h2 id="权限标识-示例" tabindex="-1">权限标识（示例） <a class="header-anchor vp-link" href="#权限标识-示例" aria-label="Permalink to &quot;权限标识（示例）&quot;">​</a></h2><p>以菜单 SQL 为准，常见形如：</p><ul><li><code>system:user:list</code>、<code>system:user:add</code>、<code>system:user:edit</code>、<code>system:user:remove</code></li><li><code>system:user:export</code>、<code>system:user:import</code>、<code>system:user:resetPwd</code></li></ul><p>前端按钮使用 <code>v-hasPermi=&quot;[&#39;system:user:add&#39;]&quot;</code>。</p><h2 id="数据权限" tabindex="-1">数据权限 <a class="header-anchor vp-link" href="#数据权限" aria-label="Permalink to &quot;数据权限&quot;">​</a></h2><p>用户列表受<strong>角色数据权限</strong>约束（全部 / 自定义 / 本部门 / 本部门及以下 / 仅本人），由角色模块 <code>dataScope</code> 配置，Service 层拼接数据范围条件。</p><h2 id="开发注意" tabindex="-1">开发注意 <a class="header-anchor vp-link" href="#开发注意" aria-label="Permalink to &quot;开发注意&quot;">​</a></h2><ul><li>密码入库经 <code>PasswordCodec</code>（BCrypt + 可配置 SM4 传输层），禁止明文日志。</li><li>导入失败应返回可下载的错误行文件（<code>importError</code>）。</li><li>管理员账号受保护，删除/停用需业务校验。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor vp-link" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./permission-management.html" class="vp-link">权限管理</a></li><li><a href="./../api/user.html" class="vp-link">用户接口</a></li></ul>',16)])])}const p=d(o,[["render",c]]);export{m as __pageData,p as default};
